package main

import (
	"archive/zip"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"strings"
)

const uploadDir = "/var/app/uploads"
const extractDir = "/var/app/data"

func main() {
	http.HandleFunc("/upload", handleUpload)
	http.HandleFunc("/health", func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(200)
		w.Write([]byte("ok"))
	})
	fmt.Println("Starting server on :8080")
	http.ListenAndServe(":8080", nil)
}

func handleUpload(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	file, header, err := r.FormFile("archive")
	if err != nil {
		http.Error(w, "Failed to read file", http.StatusBadRequest)
		return
	}
	defer file.Close()

	// Save uploaded zip to disk
	zipPath := filepath.Join(uploadDir, header.Filename)
	out, err := os.Create(zipPath)
	if err != nil {
		http.Error(w, "Failed to save file", http.StatusInternalServerError)
		return
	}
	io.Copy(out, file)
	out.Close()

	// Extract zip contents
	extracted, err := extractZip(zipPath, extractDir)
	if err != nil {
		http.Error(w, fmt.Sprintf("Extraction failed: %v", err), http.StatusInternalServerError)
		return
	}

	w.WriteHeader(http.StatusOK)
	fmt.Fprintf(w, "Extracted %d files successfully\n", extracted)
}

func extractZip(zipPath string, destDir string) (int, error) {
	reader, err := zip.OpenReader(zipPath)
	if err != nil {
		return 0, err
	}
	defer reader.Close()

	count := 0
	for _, f := range reader.File {
		// Basic sanitization: reject absolute paths
		if filepath.IsAbs(f.Name) {
			continue
		}

		// Construct target path - NOTE: filepath.Join does NOT prevent
		// directory traversal with "../" components
		targetPath := filepath.Join(destDir, f.Name)

		// Additional check: ensure no null bytes (common in other attacks)
		if strings.Contains(targetPath, "\x00") {
			continue
		}

		if f.FileInfo().IsDir() {
			os.MkdirAll(targetPath, 0755)
			continue
		}

		// Ensure parent directory exists
		os.MkdirAll(filepath.Dir(targetPath), 0755)

		// Extract file
		outFile, err := os.OpenFile(targetPath, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, f.Mode())
		if err != nil {
			return count, fmt.Errorf("failed to create %s: %w", targetPath, err)
		}

		rc, err := f.Open()
		if err != nil {
			outFile.Close()
			return count, fmt.Errorf("failed to open zip entry: %w", err)
		}

		_, err = io.Copy(outFile, rc)
		rc.Close()
		outFile.Close()
		if err != nil {
			return count, fmt.Errorf("failed to write %s: %w", targetPath, err)
		}
		count++
	}
	return count, nil
}
